// src/pages/Transportadoras.js
import React, { useState } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer
} from 'recharts';
import 'chart.js/auto';
import ChartDataLabels from 'chartjs-plugin-datalabels';
import { Chart as ChartJS } from 'chart.js';
ChartJS.register(ChartDataLabels);

// --- DADOS FIXOS ------------------------------------------------------------
const transportadoras = [
  'A MARQUES TRANSPORTES',
  'NOVA DIRECAO TRANSP EIRELI',
  'LUMA EXPRESS TRANSP CARGA LTDA',
  'W.C.CARVALHO TRANSPORTES',
  'NOVA LESTE TRANSPORTES ME',
  'MARIA LUIZA DA S L TRANSPORTE',
  'ANDERSON RODRIGUES DOS SANTOS',
  'D SANTANA',
  'T CARGO TRANSPORTES LOGISTICA',
  'SARAIVA TRANSPORTES LTDA',
  'TRANSCORTE TRANSPORTADORA E LOGISTICA'
];

const lojasFixas = [
  { cd_loja: '1000', nome: 'Matriz' },
  { cd_loja: '1001', nome: 'Gasômetro' },
  { cd_loja: '1003', nome: 'Paes Leme' },
  { cd_loja: '1006', nome: 'Santos' },
  { cd_loja: '1007', nome: 'São José' },
];

const tiposEntregaFixos = [5, 6, 7, 10, 13];

// --- GERAÇÃO DE DADOS DINÂMICOS --------------------------------------------
const gerarDados = () => {
  const data = {};

  transportadoras.forEach((t) => {
    const lojaData = lojasFixas.map((loja) => {
      // TOTAL PREVISTO E EMITIDO DE NOTAS
      const qtdNotasPrevistas = Math.floor(Math.random() * 20) + 20;  // 20‑39
      const qtdNotasEmitidas  = Math.floor(Math.random() * qtdNotasPrevistas); // 0‑previstas

      const valorFrete = parseFloat((Math.random() * 3000 + 500).toFixed(2));

      const tipos = tiposEntregaFixos.map((tp) => ({
        tpEntrega: tp,
        qtdNotas: Math.floor(Math.random() * 6),
        valorFrete: parseFloat((Math.random() * 800 + 50).toFixed(2)),
      }));

      return {
        ...loja,
        qtdNotasEmitidas,
        qtdNotasPrevistas,
        valorFrete,
        tipos,
      };
    });

    const totalNotasEmitidas = lojaData.reduce((sum, l) => sum + l.qtdNotasEmitidas, 0);
    const totalNotasPrevistas = lojaData.reduce((sum, l) => sum + l.qtdNotasPrevistas, 0);
    const totalFrete = lojaData.reduce((sum, l) => sum + l.valorFrete, 0);

    data[t] = {
      lojas: lojaData,
      totalNotasEmitidas,
      totalNotasPrevistas,
      totalFrete,
    };
  });
  return data;
};

const gerarFaturamentoMensal = () => {
  const data = {};
  transportadoras.forEach((t) => {
    const meses = Array.from({ length: 12 }, (_, i) => ({
      mes: `${i + 1}`.padStart(2, '0'),
      valor: parseFloat((Math.random() * 10000 + 2000).toFixed(2)),
    }));
    data[t] = meses;
  });
  return data;
};

const dadosPorTransportadora = gerarDados();
const faturamentoMensalPorTransportadora = gerarFaturamentoMensal();

// --- COMPONENTE -------------------------------------------------------------
export default function Transportadoras() {
  const [ano, setAno] = useState(new Date().getFullYear());
  const [mes, setMes] = useState(new Date().getMonth() + 1);
  const [quinzena, setQuinzena] = useState(1);
  const [selecionada, setSelecionada] = useState(null);
  const [selectedLoja, setSelectedLoja] = useState(null);
  const [selectedTipoEntrega, setSelectedTipoEntrega] = useState(null);

  // --- TRANSPORTADORAS ORDENADAS POR NOTAS EMITIDAS ------------------------
  const transportadorasOrdenadas = transportadoras
    .map((nome) => ({
      nome,
      notasEmitidas: dadosPorTransportadora[nome].totalNotasEmitidas,
      notasPrevistas: dadosPorTransportadora[nome].totalNotasPrevistas,
      frete: dadosPorTransportadora[nome].totalFrete,
    }))
    .sort((a, b) => b.notasEmitidas - a.notasEmitidas);

  // --- LOJAS DA TRANSPORTADORA SELECIONADA ----------------------------------
  const lojas = selecionada ? dadosPorTransportadora[selecionada].lojas : [];

  // --- TIPOS FILTRADOS ------------------------------------------------------
  const tiposFiltrados = () => {
    if (!selecionada || !selectedLoja) return [];
    const loja = lojas.find((l) => l.cd_loja === selectedLoja);
    return loja ? loja.tipos : [];
  };

  // --- TIPOS GERAL ----------------------------------------------------------
  const tiposGeral = () => {
    if (!selecionada) return [];
    const tiposTotais = {};
    lojas.forEach((l) => {
      l.tipos.forEach((t) => {
        if (!tiposTotais[t.tpEntrega]) {
          tiposTotais[t.tpEntrega] = { tpEntrega: t.tpEntrega, qtdNotas: 0 };
        }
        tiposTotais[t.tpEntrega].qtdNotas += t.qtdNotas;
      });
    });
    return Object.values(tiposTotais);
  };

  // --- TOTAIS GERAIS --------------------------------------------------------
  const totalNotasEmitidasGeral = transportadorasOrdenadas.reduce((acc, t) => acc + t.notasEmitidas, 0);
  const totalNotasPrevistasGeral = transportadorasOrdenadas.reduce((acc, t) => acc + t.notasPrevistas, 0);
  const totalFreteGeral = transportadorasOrdenadas.reduce((acc, t) => acc + t.frete, 0);

  // --- TOTAIS POR LOJA ------------------------------------------------------
  const totalNotasEmitidasLojas = lojas.reduce((acc, l) => acc + l.qtdNotasEmitidas, 0);
  const totalFreteLojas = lojas.reduce((acc, l) => acc + l.valorFrete, 0);

  return (
    <div className="p-4 space-y-6">
      {/* -------------------------------------------------------------------- */}
      {/* FILTROS                                                              */}
      {/* -------------------------------------------------------------------- */}
      <div className="flex space-x-4">
        <select className="border px-2 py-1 rounded" value={ano} onChange={(e) => setAno(+e.target.value)}>
          {Array.from({ length: 5 }, (_, i) => ano - i).map((a) => (
            <option key={a} value={a}>{a}</option>
          ))}
        </select>
        <select className="border px-2 py-1 rounded" value={mes} onChange={(e) => setMes(+e.target.value)}>
          {[...Array(12)].map((_, i) => (
            <option key={i + 1} value={i + 1}>{i + 1}</option>
          ))}
        </select>
        <select className="border px-2 py-1 rounded" value={quinzena} onChange={(e) => setQuinzena(+e.target.value)}>
          <option value={1}>1ª Quinzena</option>
          <option value={2}>2ª Quinzena</option>
        </select>
      </div>

      {/* -------------------------------------------------------------------- */}
      {/* CARDS                                                                */}
      {/* -------------------------------------------------------------------- */}
      <div className="grid grid-cols-12 gap-4">

        {/* ----------------- LEGENDA & DETALHES ----------------------------- */}
        <div className="bg-white p-4 rounded shadow overflow-auto col-span-6">
          <h2 className="text-center text-lg font-semibold mb-2">Legenda &amp; Detalhes</h2>
          <table className="w-full text-sm">
            <thead>
              <tr>
                <th className="p-2 text-left">Transportadora</th>
                <th className="p-2 text-left">Notas</th>
                <th className="p-2 text-left">Frete</th>
                <th className="p-2 text-left">%</th>
              </tr>
            </thead>
            <tbody>
              {transportadorasOrdenadas.map((d) => (
                <tr
                  key={d.nome}
                  className={`cursor-pointer hover:bg-gray-100 ${selecionada === d.nome ? 'bg-green-100 font-bold' : ''}`}
                  onClick={() => {
                    setSelecionada(d.nome);
                    setSelectedLoja(null);
                    setSelectedTipoEntrega(null);
                  }}
                >
                  <td className="p-2">{d.nome}</td>
                  <td className="p-2">{d.notasEmitidas}/{d.notasPrevistas}</td>
                  <td className="p-2">R$ {d.frete.toLocaleString()}</td>
                  <td className="p-2">{((d.notasEmitidas / totalNotasEmitidasGeral) * 100).toFixed(1)}%</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="mt-2 border-t pt-2 font-bold text-right">
            Total Notas: {totalNotasEmitidasGeral}/{totalNotasPrevistasGeral} | Total Frete: R$ {totalFreteGeral.toFixed(2)}
          </div>
        </div>

        {/* ----------------- FRETE POR LOJA -------------------------------- */}
        <div className="bg-white p-4 rounded shadow overflow-auto col-span-4">
          <h2 className="text-center font-semibold mb-2">Frete por Loja</h2>
          {!selecionada ? (
            <p className="text-center text-gray-500">Selecione uma transportadora à esquerda.</p>
          ) : (
            <>
              <table className="w-full text-sm">
                <thead>
                  <tr>
                    <th className="p-2 text-left">CD Loja</th>
                    <th className="p-2 text-left">Nome</th>
                    <th className="p-2 text-left">Qtd Notas</th>
                    <th className="p-2 text-left">Valor Frete</th>
                  </tr>
                </thead>
                <tbody>
                  {lojas.map((l) => (
                    <tr
                      key={l.cd_loja}
                      className={`hover:bg-gray-100 cursor-pointer ${selectedLoja === l.cd_loja ? 'bg-yellow-100 font-bold' : ''}`}
                      onClick={() => {
                        setSelectedLoja(l.cd_loja);
                        setSelectedTipoEntrega(null);
                      }}
                    >
                      <td className="p-2">{l.cd_loja}</td>
                      <td className="p-2">{l.nome}</td>
                      <td className="p-2">{l.qtdNotasEmitidas}</td>
                      <td className="p-2">R$ {l.valorFrete.toFixed(2)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <div className="mt-2 border-t pt-2 font-bold text-right">
                Total Notas: {totalNotasEmitidasLojas} | Total Frete: R$ {totalFreteLojas.toFixed(2)}
              </div>
            </>
          )}
        </div>

        {/* ----------------- FRETE POR TIPO ENTREGA ------------------------ */}
        <div className="bg-white p-4 rounded shadow overflow-auto col-span-2">
          <h2 className="text-center font-semibold mb-2">Frete por Tipo Entrega</h2>
          {!selecionada ? (
            <p className="text-center text-gray-500">Selecione uma transportadora à esquerda.</p>
          ) : (
            <>
              <table className="w-full text-sm">
                <thead>
                  <tr>
                    <th className="p-2 text-center">Cab</th>
                    <th className="p-2 text-center">Qtd Notas</th>
                  </tr>
                </thead>
                <tbody>
                  {(selectedLoja ? tiposFiltrados() : tiposGeral())
                    .sort((a, b) => b.qtdNotas - a.qtdNotas)
                    .map((t) => (
                      <tr
                        key={t.tpEntrega}
                        className={`hover:bg-gray-100 cursor-pointer ${selectedTipoEntrega === t.tpEntrega ? 'bg-blue-100 font-bold' : ''}`}
                        onClick={() => setSelectedTipoEntrega(t.tpEntrega)}
                      >
                        <td className="p-2 text-center">{t.tpEntrega}</td>
                        <td className="p-2 text-center">{t.qtdNotas}</td>
                      </tr>
                    ))}
                </tbody>
              </table>
              <div className="mt-2 border-t pt-2 font-bold text-right">
                Total de Notas: {(selectedLoja ? tiposFiltrados() : tiposGeral()).reduce((acc, t) => acc + t.qtdNotas, 0)}
              </div>
            </>
          )}
        </div>
      </div>

      {/* -------------------------------------------------------------------- */}
      {/* FATURAMENTO MENSAL -------------------------------------------------- */}
      {/* -------------------------------------------------------------------- */}
      {selecionada && (
        <div className="bg-white p-4 rounded shadow h-[400px]">
          <h2 className="text-center font-semibold mb-4">Faturamento Mensal - {selecionada}</h2>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={faturamentoMensalPorTransportadora[selecionada]}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="mes" label={{ value: 'Mês', position: 'insideBottom', offset: -5 }} />
              <YAxis label={{ value: 'R$', angle: -90, position: 'insideLeft' }} />
              <Tooltip formatter={(value) => `R$ ${value.toFixed(2)}`} />
              <Bar dataKey="valor" fill="#28a745" name="Faturamento" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}
    </div>
  );
}
