import { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';

import Lojas from './pages/Lojas';
import Transportadoras from './pages/Transportadoras';
import PosicaoFrotas from './pages/PosicaoFrotas';
import ListaColetasEmbarcador from './pages/ListaColetasEmbarcador';
import Login from './pages/Login';

import SidebarLayout from './components/SidebarLayout';
import SidebarLayoutTransportador from './components/SidebarLayoutTransportador';
import SidebarLayoutLoja from './components/SidebarLayoutLoja';

import TransportadorHome from './pages/TransportadorHome';
import ImportacaoCTe from './pages/ImportacaoCTe';
import Faturas from './pages/Faturas';

import Coletas from './pages/Loja/Coletas';
import ListaColetas from './pages/Loja/ListaColetas';
import CarreteirosCadastro from './pages/Loja/CarreteirosCadastro'; // importe o novo componente

import OrdemDeColetaPrint from './components/OrdemDeColetaPrint';

export default function App() {
  const [user, setUser] = useState(() => {
    const savedUser = localStorage.getItem('user');
    return savedUser ? JSON.parse(savedUser) : null;
  });

  useEffect(() => {
    if (user) localStorage.setItem('user', JSON.stringify(user));
    else localStorage.removeItem('user');
  }, [user]);

  return (
    <Router>
      <Routes>
        <Route path="/" element={<Login onLogin={setUser} />} />

        {user?.role === 'embarcador' && (
          <>
            <Route path="/dashboard" element={<Navigate to="/lojas" replace />} />

            <Route
              path="/lojas"
              element={
                <SidebarLayout user={user}>
                  <Lojas user={user} />
                </SidebarLayout>
              }
            />
            <Route
              path="/transportadoras"
              element={
                <SidebarLayout user={user}>
                  <Transportadoras user={user} />
                </SidebarLayout>
              }
            />
            <Route
              path="/posicao-frotas"
              element={
                <SidebarLayout user={user}>
                  <PosicaoFrotas user={user} />
                </SidebarLayout>
              }
            />
            <Route
              path="/lista-coletas-embarcador"
              element={
                <SidebarLayout user={{ name: "João", role: "embarcador" }}>
                  <ListaColetasEmbarcador />
                </SidebarLayout>
              }
            />
          </>
        )}

        {user?.role === 'transportador' && (
          <>
            <Route
              path="/transportador"
              element={
                <SidebarLayoutTransportador user={user}>
                  <TransportadorHome user={user} />
                </SidebarLayoutTransportador>
              }
            />
            <Route
              path="/importacao"
              element={
                <SidebarLayoutTransportador user={user}>
                  <ImportacaoCTe user={user} />
                </SidebarLayoutTransportador>
              }
            />
            <Route
              path="/faturas"
              element={
                <SidebarLayoutTransportador user={user}>
                  <Faturas user={user} />
                </SidebarLayoutTransportador>
              }
            />
          </>
        )}

        {user?.role === 'loja' && (
          <>
            <Route
              path="/loja/coletas"
              element={
                <SidebarLayoutLoja user={user}>
                  <Coletas user={user} />
                </SidebarLayoutLoja>
              }
            />
            <Route 
              path="/loja/lista-coletas" 
              element={
                <SidebarLayoutLoja user={user}>
                  <ListaColetas user={user} />
                </SidebarLayoutLoja>
              } 
            />
            <Route
              path="/loja/carreteiros"
              element={
                <SidebarLayoutLoja user={user}>
                  <CarreteirosCadastro user={user} />
                </SidebarLayoutLoja>
              }
            />
          </>
        )}

        {/* 📄 Rota para a impressão da ordem de coleta */}
        <Route path="/coleta/print/:id" element={<OrdemDeColetaPrint />} />

        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </Router>
  );
}
